args.content:
body {
    font-family: 'Roboto', sans-serif;
    margin: 0;
    padding: 20px;
    background-color: #f8f9fa;
}

h1 {
    text-align: center;
    color: #343a40;
}

.container {
    display: flex;
    justify-content: space-around;
    align-items: flex-start;
    flex-wrap: nowrap;
}

#chart-container {
    width: 60%;
    background: white;
    border-radius: 8px;
    box-shadow: 0 4px 6px rgba(0,0,0,0.1);
    padding: 10px;
    margin-right: 20px;
}

#table-container {
    width: 35%;
    max-height: 800px;
    overflow-y: auto;
    background: white;
    border-radius: 8px;
    box-shadow: 0 4px 6px rgba(0,0,0,0.1);
    padding: 10px;
}

table {
    width: 100%;
    border-collapse: collapse;
}

th, td {
    text-align: left;
    padding: 12px;
    border-bottom: 1px solid #dee2e6;
}

th {
    background-color: #f1f3f5;
    position: sticky;
    top: 0;
    z-index: 10;
}

tr:hover {
    background-color: #f1f3f5;
    cursor: pointer;
}

tr.highlighted {
    background-color: #e7f5ff !important;
    border: 2px solid #228be6;
}

.bubble {
    stroke: #fff;
    stroke-width: 1.5px;
    transition: opacity 0.2s;
}

.bubble:hover {
    stroke: #000;
    stroke-width: 2px;
    cursor: pointer;
}

.bubble.highlighted {
    stroke: #228be6;
    stroke-width: 3px;
}

.label {
    font-size: 10px;
    font-weight: bold;
    pointer-events: none;
    text-anchor: middle;
    fill: #333;
}

#tooltip {
    position: absolute;
    text-align: left;
    padding: 8px;
    font: 12px sans-serif;
    background: rgba(0, 0, 0, 0.8);
    color: #fff;
    border: 0px;
    border-radius: 4px;
    pointer-events: none;
    opacity: 0;
    z-index: 1000;
}

.legend-container {
    margin-top: 20px;
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
}

.legend-item {
    display: flex;
    align-items: center;
    margin: 5px 15px;
    font-size: 12px;
}

.legend-color {
    width: 12px;
    height: 12px;
    margin-right: 5px;
    border-radius: 50%;
}

