document.addEventListener('DOMContentLoaded', () => {
    const margin = { top: 20, right: 20, bottom: 20, left: 20 };
    const width = 800 - margin.left - margin.right;
    const height = 600 - margin.top - margin.bottom;

    const svg = d3.select("#bubble-chart")
        .append("svg")
        .attr("width", width + margin.left + margin.right)
        .attr("height", height + margin.top + margin.bottom)
        .append("g")
        .attr("transform", `translate(${margin.left},${margin.top})`);

    const tooltip = d3.select("#tooltip");

    function formatMarketCap(val) {
        if (!val || isNaN(val) || val === 0) return "N/A";
        const suffixes = ["", "K", "M", "B", "T"];
        let suffixNum = 0;
        let tempVal = val;
        while (tempVal >= 1000 && suffixNum < suffixes.length - 1) {
            tempVal /= 1000;
            suffixNum++;
        }
        return tempVal.toFixed(2) + suffixes[suffixNum];
    }

    d3.csv("data/stock-descriptions.csv").then(data => {
        // Clean and parse data
        data.forEach(d => {
            d.marketCap = +d.marketCap;
            d.isETF = d.sector === "ETF";
        });

        // Filter out empty lines or invalid tickers if any
        data = data.filter(d => d.ticker);

        // Sort data for table
        const sortedData = [...data].sort((a, b) => b.marketCap - a.marketCap);

        // Table Implementation
        const tbody = d3.select("#stock-table tbody");
        const rows = tbody.selectAll("tr")
            .data(sortedData)
            .enter()
            .append("tr")
            .attr("id", d => `row-${d.ticker}`)
            .on("click", (event, d) => {
                highlightStock(d.ticker);
            });

        rows.append("td").text(d => d.ticker);
        rows.append("td").text(d => d['full name']);
        rows.append("td").text(d => d.sector);
        rows.append("td").text(d => formatMarketCap(d.marketCap));

        // Bubble Chart Implementation
        const sectors = Array.from(new Set(data.map(d => d.sector)));
        const colorScale = d3.scaleOrdinal()
            .domain(sectors)
            .range(d3.schemeCategory10);

        // Legend
        const legend = d3.select("#legend");
        sectors.forEach(sector => {
            const item = legend.append("div").attr("class", "legend-item");
            item.append("div")
                .attr("class", "legend-color")
                .style("background-color", colorScale(sector));
            item.append("span").text(sector);
        });

        // Scales
        const maxCap = d3.max(data, d => d.marketCap);
        const radiusScale = d3.scaleSqrt()
            .domain([0, maxCap])
            .range([5, 40]);

        // ETF size
        const etfRadius = 15;

        data.forEach(d => {
            d.radius = d.isETF ? etfRadius : radiusScale(d.marketCap);
        });

        // Force Simulation
        // Sector centers
        const sectorCenters = {};
        const angleStep = (2 * Math.PI) / sectors.length;
        sectors.forEach((sector, i) => {
            sectorCenters[sector] = {
                x: width / 2 + Math.cos(i * angleStep) * 200,
                y: height / 2 + Math.sin(i * angleStep) * 200
            };
        });

        const simulation = d3.forceSimulation(data)
            .force("x", d3.forceX(d => sectorCenters[d.sector].x).strength(0.1))
            .force("y", d3.forceY(d => sectorCenters[d.sector].y).strength(0.1))
            .force("collide", d3.forceCollide(d => d.radius + 2))
            .force("center", d3.forceCenter(width / 2, height / 2))
            .on("tick", ticked);

        const bubbles = svg.selectAll(".bubble-group")
            .data(data)
            .enter()
            .append("g")
            .attr("class", "bubble-group")
            .attr("id", d => `bubble-group-${d.ticker}`)
            .on("click", (event, d) => {
                highlightStock(d.ticker);
            })
            .on("mouseover", (event, d) => {
                if (d.isETF) {
                    tooltip.transition().duration(200).style("opacity", .9);
                    tooltip.html(`<b>${d.ticker}</b><br/>${d['full name']}<br/>Sector: ${d.sector}`)
                        .style("left", (event.pageX + 10) + "px")
                        .style("top", (event.pageY - 28) + "px");
                } else {
                    tooltip.transition().duration(200).style("opacity", .9);
                    tooltip.html(`<b>${d.ticker}</b><br/>${d['full name']}<br/>Sector: ${d.sector}`)
                        .style("left", (event.pageX + 10) + "px")
                        .style("top", (event.pageY - 28) + "px");
                }
            })
            .on("mouseout", () => {
                tooltip.transition().duration(500).style("opacity", 0);
            });

        bubbles.append("circle")
            .attr("class", "bubble")
            .attr("r", d => d.radius)
            .attr("fill", d => colorScale(d.sector));

        bubbles.append("text")
            .attr("class", "label")
            .attr("dy", ".3em")
            .text(d => d.ticker)
            .style("font-size", d => Math.min(d.radius * 0.8, 12) + "px");

        function ticked() {
            bubbles.attr("transform", d => `translate(${d.x},${d.y})`);
        }

        function highlightStock(ticker) {
            // Reset previous highlights
            d3.selectAll("tr").classed("highlighted", false);
            d3.selectAll(".bubble").classed("highlighted", false);

            // Highlight new row
            const selectedRow = d3.select(`#row-${ticker}`);
            selectedRow.classed("highlighted", true);

            // Scroll to row
            const tableContainer = document.getElementById('table-container');
            const rowElement = document.getElementById(`row-${ticker}`);
            if (rowElement) {
                tableContainer.scrollTo({
                    top: rowElement.offsetTop - tableContainer.offsetTop - 100,
                    behavior: 'smooth'
                });
            }

            // Highlight bubble
            d3.select(`#bubble-group-${ticker} circle`).classed("highlighted", true);
        }
    });
});

