                    .x(d => x(d.date))
                    .y0(pcHeight)
                    .y1(d => y(d.close));

                pcSvg.append("path")
                    .datum(priceData)
                    .attr("fill", "#e7f5ff")
                    .attr("opacity", 0.5)
                    .attr("d", area);

            }).catch(err => {
                console.error("Error loading price data for", ticker, err);
                d3.select("#price-chart").text("Price data not available for this stock.");
            });
        }
    });
});

