        if (!val || isNaN(val) || val === 0) return "N/A";
        const suffixes = ["", "K", "M", "B", "T"];
        let suffixNum = 0;
        let tempVal = val;
        while (tempVal >= 1000 && suffixNum < suffixes.length - 1) {
            tempVal /= 1000;
            suffixNum++;
        }
        return tempVal.toFixed(2) + suffixes[suffixNum];
    }

